def home(request):
    return render(request, 'home.html')

def signup(request):
    if request.method == 'POST':
        print("POST data:")
        form = SignUpForm(request.POST)
        if form.is_valid():
            user = form.save()
            login(request, user)
            messages.success(request, 'Account created successfully!')
            return redirect('home')  
        else:
            messages.error(request, 'Please correct the errors below.')
    else:
        form = SignUpForm()
    return render(request, 'signup.html', {'form': form})

@login_required
def student_dashboard(request):
   
    try:
        result = AptitudeResult.objects.get(user=request.user)
        return redirect('result')
    except AptitudeResult.DoesNotExist:
        pass
    
    return render(request, 'student_dashboard.html')

@login_required
def aptitude_test(request):
    if request.method == 'POST':
        form = AptitudeTestForm(request.POST)
        if form.is_valid():
           
            scores = calculate_aptitude_scores(form.cleaned_data)
            career_info = recommend_career(scores)
            
           
            result = AptitudeResult.objects.create(
                user=request.user,
                math_score=scores['math'],
                logic_score=scores['logic'],
                creativity_score=scores['creativity'],
                science_score=scores['science'],
                commerce_score=scores['commerce'],
                recommended_career=career_info['career'],
                career_description=career_info['description'],
                roadmap=career_info['roadmap']
            )
            
            return redirect('result')
    else:
        form = AptitudeTestForm()
    
    return render(request, 'aptitude_test.html', {'form': form})

def calculate_aptitude_scores(answers):
    """Calculate scores based on correct answers and preferences"""
    scores = {
        'math': 0,
        'logic': 0,
        'creativity': 0,
        'science': 0,
        'commerce': 0
    }
    
   
    correct_answers = {
        'q1': '36', 
        'q2': '75 km/h',
        'q3': '162',  
        'q4': 'Some roses might be red',  
        'q7': 'Neutralization',  
        'q8': 'Pancreas',  
        'q9': 'Gross Domestic Product',  
        'q10': 'Return on Investment',  
    }
    
    
    if answers['q1'] == correct_answers['q1']:
        scores['math'] += 50
    if answers['q2'] == correct_answers['q2']:
        scores['math'] += 50
    
    if answers['q3'] == correct_answers['q3']:
        scores['logic'] += 50
    if answers['q4'] == correct_answers['q4']:
        scores['logic'] += 50
    
    if answers['q7'] == correct_answers['q7']:
        scores['science'] += 50
    if answers['q8'] == correct_answers['q8']:
        scores['science'] += 50
    
    if answers['q9'] == correct_answers['q9']:
        scores['commerce'] += 50
    if answers['q10'] == correct_answers['q10']:
        scores['commerce'] += 50
    
    
    if answers['q5'] in ['Art sculpture', 'Musical instrument']:
        scores['creativity'] += 50
    if answers['q6'] == 'Designing a poster':
        scores['creativity'] += 50
    elif answers['q6'] == 'Solving math problems':
        scores['math'] += 25
    elif answers['q6'] == 'Conducting experiments':
        scores['science'] += 25
    
    return scores

def recommend_career(scores):
    """Recommend career based on highest scores"""
    career_recommendations = {
        'math': {
            'career': 'Engineering / Data Science',
            'description': 'Your strong mathematical and logical thinking skills make you well-suited for engineering, computer science, or data science careers. These fields require analytical thinking and problem-solving abilities.',
            'roadmap': 'Class 12 PCM → JEE Preparation → Engineering College → Specialization in CS/IT/Data Science → Industry/Higher Studies'
        },
        'science': {
            'career': 'Medical / Biotechnology',
            'description': 'Your interest and aptitude in science subjects indicate a strong potential for medical, biological, or biotechnology careers. These fields involve research, analysis, and helping others.',
            'roadmap': 'Class 12 PCB → NEET Preparation → Medical College / B.Sc Biotechnology → Specialization → Practice/Research'
        },
        'creativity': {
            'career': 'Design / Arts / Media',
            'description': 'Your creative thinking and artistic inclination suggest careers in design, arts, media, or creative industries. These fields value innovation and creative expression.',
            'roadmap': 'Class 12 → Portfolio Development → Design School/Fine Arts → Specialization → Creative Industry'
        },
        'commerce': {
            'career': 'Business / Management / Finance',
            'description': 'Your understanding of business concepts and commerce indicates potential for careers in business, management, finance, or entrepreneurship.',
            'roadmap': 'Class 12 Commerce → CA/CS/CMA or BBA → MBA/Professional Courses → Corporate/Own Business'
        },
        'logic': {
            'career': 'Engineering / Computer Science',
            'description': 'Your logical reasoning abilities are perfect for engineering, computer science, or analytical roles that require systematic thinking.',
            'roadmap': 'Class 12 PCM → JEE/Programming → Engineering/BCA → Specialization → Tech Industry'
        }
    }
    
    
    max_score_category = max(scores, key=scores.get)
    
    
    if scores['math'] >= 75 and scores['logic'] >= 75:
        max_score_category = 'math'
    
    return career_recommendations.get(max_score_category, career_recommendations['math'])

@login_required
def result(request):
    try:
        result = AptitudeResult.objects.get(user=request.user)
        return render(request, 'result.html', {'result': result})
    except AptitudeResult.DoesNotExist:
        messages.error(request, 'Please take the aptitude test first.')
        return redirect('aptitude_test')

def college_finder(request):
    colleges = College.objects.all()
    form = CollegeFinderForm()
    
    if request.method == 'POST':
        form = CollegeFinderForm(request.POST)
        if form.is_valid():
            city = form.cleaned_data['city']
            stream = form.cleaned_data['stream']
            
            colleges = College.objects.all()
            if city:
                colleges = colleges.filter(city__icontains=city)
            if stream:
                colleges = colleges.filter(stream=stream)
            
            colleges = colleges.order_by('ranking')[:20]
    
    return render(request, 'college_finder.html', {
        'form': form,
        'colleges': colleges
    })

def workshops(request):
    workshops = Workshop.objects.filter(is_active=True).order_by('date_time')
    return render(request, 'workshops.html', {'workshops': workshops})

@login_required
def parent_dashboard(request):
    
    child_results = []
