@csrf_exempt
def chatbot_api(request):
    if request.method == 'POST':
        try:
            data = json.loads(request.body)
            user_message = data.get('message', '')
            print(f"User message: {user_message}")
            print("Session Key:", request.session.session_key)
            print("Chat History:", request.session.get("chat_history"))

           
            if "chat_history" not in request.session:
                request.session["chat_history"] = [
                    {"role": "system", "content": """You are a career counselor AI for Indian students in Class 10 and 12. 
                    Provide helpful, accurate career guidance focusing on:
                    - Career paths after Class 10/12
                    - College and university recommendations in India
                    - Entrance exam guidance (JEE, NEET, CLAT, etc.)
                    - Stream selection (Science, Commerce, Arts)
                    - Skill development advice
                    - If ask Your Then say My Name is HashNova
                    Keep responses concise, practical, and encouraging."""}
                ]

           
            request.session["chat_history"].append({"role": "user", "content": user_message})

            
            model = genai.GenerativeModel("gemini-1.5-flash")

           
            full_prompt = "\n".join([f"{m['role']}: {m['content']}" for m in request.session["chat_history"]])

            
            response = model.generate_content(full_prompt)

            ai_response = response.text

            
            request.session["chat_history"].append({"role": "assistant", "content": ai_response})
            request.session.modified = True

            return JsonResponse({'response': ai_response})

        except Exception as e:
            print(f"Error in chatbot_api: {e}")
            return JsonResponse({
                'response': 'Sorry, I am currently unavailable. Please try again later.'
            })

    return JsonResponse({'error': 'Invalid request method'})

#!/usr/bin/env python
"""Django's command-line utility for administrative tasks."""
import os
import sys


def main():
    """Run administrative tasks."""
    os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'career_platform.settings')
    try:
        from django.core.management import execute_from_command_line
    except ImportError as exc:
        raise ImportError(
            "Couldn't import Django. Are you sure it's installed and "
            "available on your PYTHONPATH environment variable? Did you "
            "forget to activate a virtual environment?"
        ) from exc
    execute_from_command_line(sys.argv)


if __name__ == '__main__':
    main()

